test-code.code:
import net.jcip.annotations.GuardedBy

class Bad1 {
    @GuardedBy("this")
    var txt: String = ""

    fun setText(t: String) { txt = t } // bad
}

import net.jcip.annotations.GuardedBy

class Bad2 {
    @GuardedBy("this")
    var txt: String = ""

    fun getText(): String { return txt } // bad
}

import net.jcip.annotations.GuardedBy

class Bad3 {
    @GuardedBy("this")
    var txt: String = ""

    fun getText(): String { return txt } // bad
    fun setText(t: String) { txt = t }   // bad
}

import net.jcip.annotations.GuardedBy

class Bad4 {
    @GuardedBy("this")
    var txt: String = ""

    @Synchronized
    fun setText(t: String) { txt = t } // good

    fun getText(): String { return txt } // bad - not synchronized
}

import net.jcip.annotations.GuardedBy

class Bad5 {
    companion object {
        @GuardedBy("this")
        var shared: String = ""
    }

    fun setShared(t: String) { shared = t } // bad
}

import net.jcip.annotations.GuardedBy

class Good1 {
    @GuardedBy("this")
    var txt: String = ""

    @Synchronized
    fun getText(): String { return txt } // good
    @Synchronized
    fun setText(t: String) { txt = t }   // good
}

import net.jcip.annotations.GuardedBy

class Good2 {
    @GuardedBy("this")
    var txt: String = ""

    fun getText(): String {
        return synchronized(this) { txt } // good
    }
    fun setText(t: String) {
        synchronized(this) { txt = t }    // good
    }
}

import net.jcip.annotations.GuardedBy

class Good3 {
    @GuardedBy("this")
    var txt: String = ""

    fun getText(): String {
        return synchronized(this@Good3) { txt } // good - this@label
    }
}

import net.jcip.annotations.GuardedBy
import org.springframework.beans.factory.annotation.Autowired

class Good4 {
    @GuardedBy("this")
    var txt: String = ""

    @Autowired
    fun init(t: String) { txt = t } // good - framework injection
}

class Good5 {
    var txt: String = ""

    fun setText(t: String) { txt = t } // good - no @GuardedBy
}

import net.jcip.annotations.GuardedBy

class Good6 {
    private val lock = Any()

    @GuardedBy("lock")
    var txt: String = ""

    fun setText(t: String) { txt = t } // not this rule's concern
}
